import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_conv2d_detail {

enum : int {
    TILE_H  = 32,
    TILE_W  = 32,
    BLOCK_H = 16,
    BLOCK_W = 16,
    THREADS = BLOCK_H * BLOCK_W,
    OC_TILE = 8
};

__global__ void cute_conv2d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ b_ptr,
    float* __restrict__ y_ptr,
    int N,
    int C,
    int H,
    int W,
    int OC,
    int KH,
    int KW,
    int OH,
    int OW,
    int stride,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    int patch_h,
    int patch_w,
    bool has_bias)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * BLOCK_W + tx;
    const int block_oh = blockIdx.y * TILE_H;
    const int block_ow = blockIdx.x * TILE_W;
    const int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    const int n = blockIdx.z / oc_tiles;
    const int oc_base = (blockIdx.z % oc_tiles) * OC_TILE;
    auto gX = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(N, C, H, W),
        make_stride(C * H * W, H * W, W, Int<1>{}));
    auto gW = make_tensor(
        make_gmem_ptr(w_ptr),
        make_shape(OC, C, KH, KW),
        make_stride(C * KH * KW, KH * KW, KW, Int<1>{}));
    auto gY = make_tensor(
        make_gmem_ptr(y_ptr),
        make_shape(N, OC, OH, OW),
        make_stride(OC * OH * OW, OH * OW, OW, Int<1>{}));
    auto gB = make_tensor(
        make_gmem_ptr(b_ptr),
        make_shape(OC),
        make_stride(Int<1>{}));
    extern __shared__ float smem[];
    auto sX = make_tensor(
        make_smem_ptr(smem),
        make_shape(patch_h, patch_w),
        make_stride(patch_w, Int<1>{}));
    float* smw_ptr = smem + patch_h * patch_w;
    auto sW = make_tensor(
        make_smem_ptr(smw_ptr),
        make_shape(OC_TILE, KH, KW),
        make_stride(KH * KW, KW, Int<1>{}));
    const int base_h = block_oh * stride - pad_h;
    const int base_w = block_ow * stride - pad_w;
    float acc[2][2][OC_TILE];
    for (int oy = 0; oy < 2; ++oy) {
        for (int ox = 0; ox < 2; ++ox) {
            for (int oci = 0; oci < OC_TILE; ++oci) {
                const int oc = oc_base + oci;
                acc[oy][ox][oci] =
                    (has_bias && oc < OC) ? gB(oc) : 0.0f;
            }
        }
    }
    for (int ic = 0; ic < C; ++ic) {
        for (int q = tid; q < patch_h * patch_w; q += THREADS) {
            const int ph = q / patch_w;
            const int pw = q - ph * patch_w;
            const int ih = base_h + ph;
            const int iw = base_w + pw;
            if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                sX(ph, pw) = gX(n, ic, ih, iw);
            } else {
                sX(ph, pw) = 0.0f;
            }
        }
        __syncthreads();
        for (int q = tid; q < OC_TILE * KH * KW; q += THREADS) {
            const int oci = q / (KH * KW);
            const int rem = q - oci * KH * KW;
            const int kh = rem / KW;
            const int kw = rem - kh * KW;
            const int oc = oc_base + oci;
            sW(oci, kh, kw) = (oc < OC) ? gW(oc, ic, kh, kw) : 0.0f;
        }
        __syncthreads();
        for (int oy = 0; oy < 2; ++oy) {
            for (int ox = 0; ox < 2; ++ox) {
                const int oh = block_oh + ty + oy * BLOCK_H;
                const int ow = block_ow + tx + ox * BLOCK_W;
                if (oh < OH && ow < OW) {
                    const int local_h =
                        (ty + oy * BLOCK_H) * stride;
                    const int local_w =
                        (tx + ox * BLOCK_W) * stride;
                    for (int kh = 0; kh < KH; ++kh) {
                        for (int kw = 0; kw < KW; ++kw) {
                            const int sh = local_h + kh * dilation_h;
                            const int sw = local_w + kw * dilation_w;
                            const float input = sX(sh, sw);
                            for (int oci = 0; oci < OC_TILE; ++oci) {
                                const int oc = oc_base + oci;
                                if (oc < OC) {
                                    acc[oy][ox][oci] +=
                                        input * sW(oci, kh, kw);
                                }
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    for (int oy = 0; oy < 2; ++oy) {
        for (int ox = 0; ox < 2; ++ox) {
            const int oh = block_oh + ty + oy * BLOCK_H;
            const int ow = block_ow + tx + ox * BLOCK_W;
            if (oh < OH && ow < OW) {
                for (int oci = 0; oci < OC_TILE; ++oci) {
                    const int oc = oc_base + oci;
                    if (oc < OC) {
                        gY(n, oc, oh, ow) = acc[oy][ox][oci];
                    }
                }
            }
        }
    }
}

} // namespace cute_conv2d_detail

torch::Tensor cute_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    const int N = static_cast<int>(x.size(0));
    const int C = static_cast<int>(x.size(1));
    const int H = static_cast<int>(x.size(2));
    const int W = static_cast<int>(x.size(3));

    const int OC = static_cast<int>(weight.size(0));
    const int WC = static_cast<int>(weight.size(1));
    const int KH = static_cast<int>(weight.size(2));
    const int KW = static_cast<int>(weight.size(3));

    TORCH_CHECK(WC == C, "weight input channels mismatch");
    TORCH_CHECK(!bias.defined() || bias.numel() == 0 || bias.numel() == OC,
                "bias shape mismatch");

    const int effective_kh = dilation_h * (KH - 1) + 1;
    const int effective_kw = dilation_w * (KW - 1) + 1;

    const int OH = (H + 2 * pad_h - effective_kh) / stride + 1;
    const int OW = (W + 2 * pad_w - effective_kw) / stride + 1;

    TORCH_CHECK(OH >= 0 && OW >= 0, "invalid convolution output size");

    auto y = torch::empty({N, OC, OH, OW}, x.options());

    const int patch_h =
        (cute_conv2d_detail::TILE_H - 1) * stride + effective_kh;
    const int patch_w =
        (cute_conv2d_detail::TILE_W - 1) * stride + effective_kw;

    const bool has_bias = bias.defined() && bias.numel() != 0;
    auto bias_c = has_bias ? bias.contiguous()
                           : torch::empty({0}, x.options());

    dim3 block(cute_conv2d_detail::BLOCK_W,
              cute_conv2d_detail::BLOCK_H);
    dim3 grid(
        (OW + cute_conv2d_detail::TILE_W - 1) /
            cute_conv2d_detail::TILE_W,
        (OH + cute_conv2d_detail::TILE_H - 1) /
            cute_conv2d_detail::TILE_H,
        N * ((OC + cute_conv2d_detail::OC_TILE - 1) / cute_conv2d_detail::OC_TILE));
    const size_t shared_bytes =
        (static_cast<size_t>(patch_h) * static_cast<size_t>(patch_w) +
         static_cast<size_t>(cute_conv2d_detail::OC_TILE) *
             static_cast<size_t>(KH) * static_cast<size_t>(KW)) *
        sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv2d_detail::cute_conv2d_kernel<<<grid, block, shared_bytes, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N,
        C,
        H,
        W,
        OC,
        KH,
        KW,
        OH,
        OW,
        stride,
        pad_h,
        pad_w,
        dilation_h,
        dilation_w,
        patch_h,
        patch_w,
        has_bias);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE convolution kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        bias: bool = False,
    ):
        super().__init__()

        self.conv2d = nn.Conv2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.conv2d.weight.contiguous()

        if self.conv2d.bias is None:
            bias = torch.empty(
                (0,),
                device=x.device,
                dtype=x.dtype,
            )
        else:
            bias = self.conv2d.bias.contiguous()

        return self._ext.cute_conv2d(
            x,
            weight,
            bias,
            self.stride,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
        )

